<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { listarPendientesExternos, validarExterno } from '../services/externo'
import type { DocumentoExterno } from '../interfaces/externo.interface'
import type { CatalogOption } from '../../interfaces/documento'
const items=ref<DocumentoExterno[]>([]),tipos=ref<CatalogOption[]>([]),context=ref<CatalogOption|null>(null),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),selected=ref<DocumentoExterno|null>(null)
const form=reactive({tipo_documento_id:0,numero:'',asunto:'',observacion:'',ruc:'',razon_social:'',apellido_paterno:'',apellido_materno:'',nombre:'',dni:'',celular:'',email:''})
async function load(page=1){loading.value=true;error.value='';try{const r=await listarPendientesExternos(page);items.value=r.data;tipos.value=r.tipos_documento;context.value=r.contexto?.instancia_activa||null;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar los documentos.'}finally{loading.value=false}}
function open(i:DocumentoExterno){selected.value=i;Object.assign(form,{tipo_documento_id:i.tipo_documento_id||0,numero:i.numero||'',asunto:i.asunto||'',observacion:i.observacion||'',ruc:i.ruc||i.remitente?.ruc||'',razon_social:i.razon_social||i.remitente?.razon_social||'',apellido_paterno:i.apellido_paterno||i.remitente?.apellido_paterno||'',apellido_materno:i.apellido_materno||i.remitente?.apellido_materno||'',nombre:i.nombre||i.remitente?.nombre||'',dni:i.dni||i.remitente?.dni||'',celular:i.celular||i.remitente?.celular||'',email:i.email||i.remitente?.email||''})}
async function validate(){if(!selected.value||!form.tipo_documento_id||!form.numero.trim()||!form.asunto.trim()||!form.observacion.trim()){error.value='Complete tipo documental, número, asunto y observación.';return}saving.value=true;try{await validarExterno(selected.value.id,{...form});success.value='Documento validado e ingresado al flujo interno.';selected.value=null;await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo validar.'}finally{saving.value=false}}
function sender(i:DocumentoExterno){return i.razon_social||i.remitente?.razon_social||[i.nombre||i.remitente?.nombre,i.apellido_paterno||i.remitente?.apellido_paterno,i.apellido_materno||i.remitente?.apellido_materno].filter(Boolean).join(' ')||'Remitente externo'}
function date(v:string){return new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}
onMounted(()=>load())
</script>
<template><div class="validation"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Trámite externo / Validar</nav><header class="hero"><div class="mark">✓</div><div><small>Trámite externo</small><h1>Documentos por validar</h1><p>Revisa la información presentada antes de incorporarla al flujo interno.</p></div><aside v-if="context"><b>{{context.nombre}}</b><span>Instancia receptora</span></aside><strong>{{pagination.total}} pendientes</strong></header><div v-if="success" class="flash">✓ {{success}}</div><div v-if="error" class="flash error">{{error}}</div><div v-if="loading" class="notice">Cargando documentos externos…</div><div v-else-if="!items.length" class="notice"><b>No hay documentos pendientes</b><span>Todos los documentos externos fueron revisados.</span></div><section v-else class="list"><article v-for="i in items" :key="i.id"><div class="file">PDF</div><div class="info"><small>Solicitud externa #{{i.id}}</small><h2>{{i.numero||'Sin número'}} · {{i.asunto}}</h2><p>{{sender(i)}}</p><span>{{i.ruc||i.dni||i.remitente?.ruc||i.remitente?.dni||'Sin identificación'}} · {{date(i.created_at)}}</span></div><div class="contact"><span>Contacto</span><b>{{i.celular||i.remitente?.celular||'—'}}</b><small>{{i.email||i.remitente?.email||'—'}}</small></div><button @click="open(i)">Revisar y validar</button></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><small>Validación externa #{{selected.id}}</small><h2>{{sender(selected)}}</h2></div><button @click="selected=null">×</button></header><form @submit.prevent="validate"><h3>Datos del remitente</h3><div class="grid"><template v-if="form.ruc"><label><span>RUC</span><input v-model.trim="form.ruc"></label><label><span>Razón social</span><input v-model.trim="form.razon_social"></label></template><template v-else><label><span>DNI</span><input v-model.trim="form.dni"></label><label><span>Nombres</span><input v-model.trim="form.nombre"></label><label><span>Apellido paterno</span><input v-model.trim="form.apellido_paterno"></label><label><span>Apellido materno</span><input v-model.trim="form.apellido_materno"></label></template><label><span>Celular</span><input v-model.trim="form.celular"></label><label><span>Correo</span><input v-model.trim="form.email" type="email"></label></div><h3>Datos del documento</h3><div class="grid"><label><span>Tipo documental *</span><select v-model="form.tipo_documento_id"><option :value="0" disabled>Seleccione</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Número *</span><input v-model.trim="form.numero"></label><label class="wide"><span>Asunto *</span><input v-model.trim="form.asunto"></label><label class="wide"><span>Dirección y observaciones *</span><textarea v-model.trim="form.observacion" rows="3"></textarea></label></div><div v-if="selected.archivo" class="attachment"><b>Archivo adjunto disponible</b><span>{{selected.archivo}}</span></div><footer><button type="button" class="clear" @click="selected=null">Cancelar</button><button :disabled="saving">{{saving?'Validando…':'Validar e ingresar'}}</button></footer></form></section></div></div></template>
<style scoped>
.validation{--accent:#d17a25;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-weight:700}.hero small,.modal>header small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero aside{margin-left:auto;text-align:right}.hero aside b,.hero aside span{display:block;font-size:.64rem}.hero aside span{color:#89959b}.hero>strong{padding:7px 9px;border-radius:15px;color:#9a5718;background:#fff0df;font-size:.61rem}.flash{margin-top:14px;padding:11px;border:1px solid #b9dfce;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.68rem}.flash.error{color:#a13f43;border-color:#efcaca;background:#fff4f4}.notice{margin-top:16px;padding:50px;display:flex;align-items:center;flex-direction:column;gap:6px;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.69rem}.list{margin-top:16px;border:1px solid #e0e6e9;border-radius:11px;background:#fff}.list article{padding:15px;display:grid;grid-template-columns:45px 1fr 160px auto;align-items:center;gap:13px;border-top:1px solid #edf0f2}.list article:first-child{border:0}.file{width:42px;height:42px;display:grid;place-items:center;border-radius:8px;color:#b04747;background:#fae8e8;font-size:.57rem;font-weight:700}.info small,.info span,.contact span,.contact small{display:block;color:#89959b;font-size:.56rem}.info h2{margin:2px 0;font-size:.74rem}.info p{margin:0;font-size:.62rem}.contact b{font-size:.64rem}.list article>button,.pagination button,.modal footer button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.62rem}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,720px);max-height:calc(100vh - 40px);overflow:auto;border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal>form{padding:20px}.modal h3{margin:3px 0 12px;padding-bottom:7px;border-bottom:1px solid #edf0f2;font-size:.75rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:17px}.wide{grid-column:1/-1}label span{display:block;margin-bottom:5px;color:#66737a;font-size:.62rem}input,select,textarea{width:100%;padding:9px 10px;border:1px solid #dae2e6;border-radius:7px;background:#fff;font:inherit;font-size:.67rem}input,select{height:39px}.attachment{padding:10px;border-radius:7px;color:#277158;background:#eaf7f1;font-size:.62rem}.attachment b,.attachment span{display:block}.modal footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}@media(max-width:750px){.hero{flex-wrap:wrap}.hero aside{margin:0;width:100%;text-align:left}.list article{grid-template-columns:45px 1fr}.contact,.list article>button{grid-column:2}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
